CREATE FUNCTION private.categories_seed_defaults(p_office_id uuid) RETURNS void
LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$
 INSERT INTO private.service_categories(office_id,name,system_key)
 SELECT p_office_id,v.name,v.system_key FROM (VALUES
 ('Documentos','documents'),('Cópias e impressões',NULL),('Digitação',NULL),('Plastificação',NULL),
 ('Certidões',NULL),('Registros',NULL),('Consultoria',NULL),('Contabilidade',NULL),
 ('Fiscal',NULL),('Trabalhista',NULL),('Rural',NULL),('Previdenciário',NULL),
 ('Jurídico',NULL),('Atendimento',NULL),('Outros',NULL)) v(name,system_key)
 ON CONFLICT DO NOTHING;
$$;
SELECT private.categories_seed_defaults(o.id) FROM public.offices o;
-- Keep every previously configured legacy name, including historical versions.
INSERT INTO private.service_categories(office_id,name)
 SELECT DISTINCT office_id,btrim(category) FROM public.service_versions
 WHERE char_length(btrim(category)) BETWEEN 1 AND 60 AND btrim(category) !~ '[[:cntrl:]]'
 ON CONFLICT(office_id,name) DO NOTHING;
CREATE FUNCTION private.categories_seed_office() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN PERFORM private.categories_seed_defaults(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER categories_seed_office AFTER INSERT ON public.offices
 FOR EACH ROW EXECUTE FUNCTION private.categories_seed_office();

CREATE TABLE private.service_version_categories (
 office_id uuid NOT NULL,
 service_id uuid NOT NULL,
 version_id uuid PRIMARY KEY,
 category_id uuid NOT NULL,
 FOREIGN KEY(office_id,service_id,version_id) REFERENCES public.service_versions(office_id,service_id,id),
 FOREIGN KEY(office_id,category_id) REFERENCES private.service_categories(office_id,id)
);
CREATE INDEX service_version_categories_service_idx ON private.service_version_categories(office_id,service_id,version_id);
CREATE INDEX service_version_categories_category_idx ON private.service_version_categories(office_id,category_id,service_id);
ALTER TABLE private.service_version_categories ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.service_version_categories FROM PUBLIC,anon,authenticated,service_role;
INSERT INTO private.service_version_categories(office_id,service_id,version_id,category_id)
 SELECT v.office_id,v.service_id,v.id,c.id FROM public.service_versions v
 JOIN private.service_categories c ON c.office_id=v.office_id AND c.name=btrim(v.category);
CREATE TRIGGER service_version_categories_immutable BEFORE UPDATE OR DELETE ON private.service_version_categories
 FOR EACH ROW EXECUTE FUNCTION private.services_version_immutable();
CREATE FUNCTION private.categories_link_version() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE category uuid;
BEGIN
 -- service_create/publish already hold the office row FOR UPDATE and revalidate
 -- authority after the wait; categories commands use the same lock order.
 SELECT id INTO category FROM private.service_categories
 WHERE office_id=NEW.office_id AND name=btrim(NEW.category) FOR KEY SHARE;
 IF category IS NULL THEN RAISE EXCEPTION 'SERVICES_VALIDATION' USING ERRCODE='PT422'; END IF;
 INSERT INTO private.service_version_categories(office_id,service_id,version_id,category_id)
 VALUES(NEW.office_id,NEW.service_id,NEW.id,category);
 RETURN NEW;
END $$;
CREATE TRIGGER categories_link_version AFTER INSERT ON public.service_versions
 FOR EACH ROW EXECUTE FUNCTION private.categories_link_version();
CREATE FUNCTION private.service_category_id(p_office_id uuid,p_version_id uuid) RETURNS uuid
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT category_id FROM private.service_version_categories WHERE office_id=p_office_id AND version_id=p_version_id;
$$;
CREATE FUNCTION private.service_category_name(p_office_id uuid,p_version_id uuid) RETURNS text
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT c.name FROM private.service_version_categories v JOIN private.service_categories c
 ON c.office_id=v.office_id AND c.id=v.category_id WHERE v.office_id=p_office_id AND v.version_id=p_version_id;
$$;
-- Historic category text remains intact; live display/edit metadata follows its ID.
CREATE OR REPLACE FUNCTION private.services_version_record(v public.service_versions) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT v.definition||jsonb_build_object('id',v.id,'number',v.number,'created_by',v.created_by,'created_at',v.created_at,'reason',v.reason,
 'category_id',private.service_category_id(v.office_id,v.id),'category_name',private.service_category_name(v.office_id,v.id));
$$;
CREATE OR REPLACE FUNCTION private.services_page(p_office_id uuid,p_query text,p_page integer,p_size integer) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb;total bigint;q text;catalog_at timestamptz;
BEGIN
 PERFORM private.services_actor(p_office_id);
 IF p_query IS NULL OR char_length(p_query)>120 OR p_query ~ '[[:cntrl:]]' OR p_page IS NULL OR p_page NOT BETWEEN 1 AND 100000 OR p_size IS NULL OR p_size NOT IN(3,5) THEN RAISE EXCEPTION 'SERVICES_VALIDATION' USING ERRCODE='PT422';END IF;
 q:=lower(btrim(p_query));catalog_at:=clock_timestamp();
 WITH candidates AS (
 SELECT s.id,s.code,v.name,v.category,private.service_category_id(v.office_id,v.id) category_id,
 private.service_category_name(v.office_id,v.id) category_name,v.unit,v.price_cents,v.number AS version,v.effective_from
 FROM public.services s CROSS JOIN LATERAL(SELECT ver.* FROM public.service_versions ver WHERE ver.office_id=s.office_id AND ver.service_id=s.id ORDER BY (ver.effective_from<=catalog_at) DESC,ver.number DESC LIMIT 1)v
 WHERE s.office_id=p_office_id AND (q='' OR strpos(lower(s.code),q)>0 OR strpos(lower(v.name),q)>0 OR strpos(lower(coalesce(private.service_category_name(v.office_id,v.id),v.category)),q)>0)),
 page AS(SELECT * FROM candidates ORDER BY code,id LIMIT p_size OFFSET(p_page-1)*p_size)
 SELECT(SELECT count(*) FROM candidates),coalesce((SELECT jsonb_agg(to_jsonb(page) ORDER BY code,id) FROM page),'[]'::jsonb) INTO total,result;
 RETURN jsonb_build_object('items',result,'total',total,'page',p_page,'page_size',p_size);
END $$;

CREATE OR REPLACE FUNCTION private.service_categories_state(p_office_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid;m public.memberships;manageable boolean;
BEGIN
 actor:=private.team_require_identity();
 SELECT * INTO m FROM public.memberships WHERE office_id=p_office_id AND user_id=actor AND active;
 IF m.id IS NULL OR NOT private.current_permissions(p_office_id) @> ARRAY['foundation.access'] THEN RAISE EXCEPTION 'CATEGORIES_FORBIDDEN' USING ERRCODE='PT403';END IF;
 manageable:=m.role_code IN('owner','admin') AND private.current_permissions(p_office_id) @> ARRAY['categories.manage'];
 RETURN jsonb_build_object('items',coalesce((SELECT jsonb_agg(
 jsonb_build_object('id',c.id,'name',c.name,'revision',c.revision,'is_documents',coalesce(c.system_key='documents',false))
 ||CASE WHEN manageable THEN jsonb_build_object('created_at',c.created_at,'services',
 (SELECT count(DISTINCT v.service_id) FROM private.service_version_categories v WHERE v.office_id=c.office_id AND v.category_id=c.id)) ELSE '{}'::jsonb END
 ORDER BY c.name,c.id) FROM private.service_categories c WHERE c.office_id=p_office_id),'[]'::jsonb),'can_manage',manageable);
END $$;

CREATE OR REPLACE FUNCTION private.service_categories_command(p_office_id uuid,p_command jsonb,p_idempotency_key uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid;m public.memberships;op text;nm text;reason text;cid uuid;expected integer;old_command jsonb;current private.service_categories;
BEGIN
 actor:=private.team_require_identity();
 IF p_idempotency_key IS NULL OR jsonb_typeof(p_command) IS DISTINCT FROM 'object' OR jsonb_typeof(p_command->'kind') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'CATEGORIES_VALIDATION' USING ERRCODE='PT422';END IF;
 op:=p_command->>'kind';reason:=btrim(p_command->>'reason');
 IF (op='create' AND (NOT p_command ?& ARRAY['kind','name','reason'] OR (SELECT count(*) FROM jsonb_object_keys(p_command))<>3))
 OR (op='rename' AND (NOT p_command ?& ARRAY['kind','category_id','expected_revision','name','reason'] OR (SELECT count(*) FROM jsonb_object_keys(p_command))<>5))
 OR (op='delete' AND (NOT p_command ?& ARRAY['kind','category_id','expected_revision','reason'] OR (SELECT count(*) FROM jsonb_object_keys(p_command))<>4))
 OR op NOT IN('create','rename','delete') OR jsonb_typeof(p_command->'reason') IS DISTINCT FROM 'string' OR char_length(reason) NOT BETWEEN 1 AND 500 OR reason ~ '[[:cntrl:]]' OR NOT private.templates_has_text20(reason)
 THEN RAISE EXCEPTION 'CATEGORIES_VALIDATION' USING ERRCODE='PT422';END IF;
 IF op IN('create','rename') THEN
  nm:=btrim(p_command->>'name');
  IF jsonb_typeof(p_command->'name') IS DISTINCT FROM 'string' OR char_length(nm) NOT BETWEEN 1 AND 60 OR NOT private.templates_has_text20(nm) OR nm ~ '[[:cntrl:]]' THEN RAISE EXCEPTION 'CATEGORIES_VALIDATION' USING ERRCODE='PT422';END IF;
 END IF;
 IF op IN('rename','delete') THEN
  IF jsonb_typeof(p_command->'category_id') IS DISTINCT FROM 'string' OR jsonb_typeof(p_command->'expected_revision') IS DISTINCT FROM 'number' OR p_command->>'expected_revision' !~ '^[1-9][0-9]{0,9}$' OR (p_command->>'expected_revision')::numeric>2147483645 THEN RAISE EXCEPTION 'CATEGORIES_VALIDATION' USING ERRCODE='PT422';END IF;
  expected:=(p_command->>'expected_revision')::integer;
  BEGIN cid:=(p_command->>'category_id')::uuid;EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'CATEGORIES_VALIDATION' USING ERRCODE='PT422';END;
  IF cid IS NULL THEN RAISE EXCEPTION 'CATEGORIES_VALIDATION' USING ERRCODE='PT422';END IF;
 END IF;
 -- One office lock serializes idempotency, service association, and name edits.
 PERFORM 1 FROM public.offices WHERE id=p_office_id FOR UPDATE;
 actor:=private.team_require_identity();
 SELECT * INTO m FROM public.memberships WHERE office_id=p_office_id AND user_id=actor AND active FOR SHARE;
 actor:=private.team_require_identity();
 IF m.id IS NULL OR m.role_code NOT IN('owner','admin') OR NOT private.current_permissions(p_office_id) @> ARRAY['foundation.access','categories.manage'] THEN RAISE EXCEPTION 'CATEGORIES_FORBIDDEN' USING ERRCODE='PT403';END IF;
 SELECT command INTO old_command FROM private.service_category_commands WHERE office_id=p_office_id AND actor_id=actor AND idempotency_key=p_idempotency_key;
 IF FOUND THEN
  IF old_command<>p_command THEN RAISE EXCEPTION 'CATEGORY_CONFLICT' USING ERRCODE='PT409';END IF;
  RETURN private.service_categories_state(p_office_id);
 END IF;
 IF op<>'create' THEN
  SELECT * INTO current FROM private.service_categories WHERE office_id=p_office_id AND id=cid FOR UPDATE;
  actor:=private.team_require_identity();
  IF NOT EXISTS(SELECT FROM public.memberships WHERE id=m.id AND active AND role_code IN('owner','admin')) OR NOT private.current_permissions(p_office_id) @> ARRAY['foundation.access','categories.manage'] THEN RAISE EXCEPTION 'CATEGORIES_FORBIDDEN' USING ERRCODE='PT403';END IF;
  IF current.id IS NULL THEN RAISE EXCEPTION 'CATEGORY_NOT_FOUND' USING ERRCODE='PT404';END IF;
  IF current.revision<>expected THEN RAISE EXCEPTION 'CATEGORY_CONFLICT' USING ERRCODE='PT409';END IF;
 END IF;
 IF op IN('create','rename') AND EXISTS(SELECT FROM private.service_categories WHERE office_id=p_office_id AND lower(name)=lower(nm) AND (cid IS NULL OR id<>cid)) THEN RAISE EXCEPTION 'CATEGORY_CONFLICT' USING ERRCODE='PT409';END IF;
 IF op='create' THEN
  INSERT INTO private.service_categories(office_id,name,created_by,system_key) VALUES(p_office_id,nm,actor,
  CASE WHEN nm='Documentos' AND NOT EXISTS(SELECT FROM private.service_categories WHERE office_id=p_office_id AND system_key='documents') THEN 'documents' END) RETURNING id INTO cid;
 ELSIF op='rename' THEN
  UPDATE private.service_categories SET name=nm,revision=revision+1 WHERE id=cid;
 ELSE
  IF EXISTS(SELECT FROM private.service_version_categories WHERE office_id=p_office_id AND category_id=cid) THEN RAISE EXCEPTION 'CATEGORY_IN_USE' USING ERRCODE='PT409';END IF;
  DELETE FROM private.service_categories WHERE id=cid;
 END IF;
 INSERT INTO private.service_category_commands(office_id,actor_id,idempotency_key,command) VALUES(p_office_id,actor,p_idempotency_key,p_command);
 -- The immutable command stores the reason; the public audit event carries no text.
 PERFORM private.emit_business_event(p_office_id,'categories.'||CASE op WHEN 'create' THEN 'created' WHEN 'rename' THEN 'renamed' ELSE 'deleted' END,'service_category',cid,p_idempotency_key,'{}');
 RETURN private.service_categories_state(p_office_id);
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'CATEGORY_CONFLICT' USING ERRCODE='PT409';
 WHEN foreign_key_violation THEN RAISE EXCEPTION 'CATEGORY_IN_USE' USING ERRCODE='PT409';
END $$;

